export type Expr =
  | { readonly kind: "literal"; readonly value: bigint }
  | { readonly kind: "add"; readonly left: Expr; readonly right: Expr }
  | {
      readonly kind: "divide";
      readonly numerator: Expr;
      readonly denominator: Expr;
    }
  | { readonly kind: "negate"; readonly inner: Expr };

export type EvalResult =
  | { readonly kind: "value"; readonly value: bigint }
  | { readonly kind: "division_by_zero" };

export function evaluate(expression: Expr): EvalResult {
  switch (expression.kind) {
    case "literal":
      return { kind: "value", value: expression.value };

    case "add": {
      const leftResult = evaluate(expression.left);

      switch (leftResult.kind) {
        case "division_by_zero":
          return leftResult;
        case "value": {
          const rightResult = evaluate(expression.right);

          switch (rightResult.kind) {
            case "division_by_zero":
              return rightResult;
            case "value":
              return {
                kind: "value",
                value: leftResult.value + rightResult.value,
              };
          }
        }
      }
    }

    case "divide": {
      const numeratorResult = evaluate(expression.numerator);

      switch (numeratorResult.kind) {
        case "division_by_zero":
          return numeratorResult;
        case "value": {
          const denominatorResult = evaluate(expression.denominator);

          switch (denominatorResult.kind) {
            case "division_by_zero":
              return denominatorResult;
            case "value":
              if (denominatorResult.value === 0n) {
                return { kind: "division_by_zero" };
              }

              return {
                kind: "value",
                value: numeratorResult.value / denominatorResult.value,
              };
          }
        }
      }
    }

    case "negate": {
      const innerResult = evaluate(expression.inner);

      switch (innerResult.kind) {
        case "division_by_zero":
          return innerResult;
        case "value":
          return { kind: "value", value: -innerResult.value };
      }
    }
  }
}

