from enum import Enum


class ScoreError(Enum):
    MALFORMED = "malformed"
    INVALID_SCORE = "invalid_score"
    DUPLICATE_NAME = "duplicate_name"


@dataclass(frozen=True)
class ParsedScores:
    scores: dict[str, int]


@dataclass(frozen=True)
class ScoreFailure:
    line: int
    error: ScoreError


type ScoreResult = ParsedScores | ScoreFailure


def parse_scores(lines: list[str]) -> ScoreResult:
    scores: dict[str, int] = {}

    for line_number, line in enumerate(lines):
        equals = line.find("=")

        if equals <= 0 or line.find("=", equals + 1) != -1:
            return ScoreFailure(line_number, ScoreError.MALFORMED)

        name = line[:equals]
        text = line[equals + 1:]

        negative = text.startswith("-")
        digits = text[1:] if negative else text

        if not digits:
            return ScoreFailure(line_number, ScoreError.INVALID_SCORE)

        if len(digits) > 1 and digits[0] == "0":
            return ScoreFailure(line_number, ScoreError.INVALID_SCORE)

        if not all("0" <= character <= "9" for character in digits):
            return ScoreFailure(line_number, ScoreError.INVALID_SCORE)

        limit = 9223372036854775808 if negative else 9223372036854775807
        magnitude = 0

        for character in digits:
            digit = ord(character) - ord("0")
            if magnitude > (limit - digit) // 10:
                return ScoreFailure(line_number, ScoreError.INVALID_SCORE)
            magnitude = magnitude * 10 + digit

        score = -magnitude if negative else magnitude

